LOTE = 500


def reconstruir_movimientos(apps, schema_editor):
    """El ingreso y, si ya egresó, el egreso de cada estadía cargada antes de esta tabla.

    Con las mismas fechas y responsables que guarda la estadía, que es lo que escriben
    los servicios desde ahora: así la línea de tiempo de una estadía vieja empieza y
    termina donde dice su permanencia. Los cambios de plaza anteriores no se registraron
    nunca y no se inventan. En el MVP no hay estadías reales; esto cubre las de prueba de
    DEV y QA. Saltea las estadías que ya tienen movimientos: correrla dos veces no
    duplica nada.
    """

    Estadia = apps.get_model("programas", "Estadia")
    MovimientoEstadia = apps.get_model("programas", "MovimientoEstadia")
    # Los ids primero: así no se inserta en la tabla de movimientos mientras se recorre
    # una consulta que la mira.
    pendientes = list(Estadia.objects.filter(movimientos__isnull=True).order_by("pk").values_list("pk", flat=True))
    for inicio in range(0, len(pendientes), LOTE):
        lote = []
        for estadia in Estadia.objects.filter(pk__in=pendientes[inicio : inicio + LOTE]).select_related("motivo"):
            lote.append(
                MovimientoEstadia(
                    estadia_id=estadia.pk,
                    dispositivo_id=estadia.dispositivo_id,
                    tipo="INGRESO",
                    momento=estadia.fecha_ingreso,
                    responsable_id=estadia.ingresada_por_id,
                    plaza_destino_id=estadia.plaza_id,
                    estado_nuevo="ACTIVA",
                )
            )
            if estadia.estado == "EGRESADA" and estadia.fecha_egreso is not None:
                lote.append(
                    MovimientoEstadia(
                        estadia_id=estadia.pk,
                        dispositivo_id=estadia.dispositivo_id,
                        tipo="EGRESO",
                        momento=estadia.fecha_egreso,
                        responsable_id=estadia.egresada_por_id,
                        motivo=estadia.motivo.nombre if estadia.motivo_id else estadia.motivo_egreso,
                        plaza_origen_id=estadia.plaza_id,
                        estado_anterior="ACTIVA",
                        estado_nuevo="EGRESADA",
                    )
                )
        MovimientoEstadia.objects.bulk_create(lote)


